/**
 * @brief Overall size range constants
 */
constexpr int MIN_PROFILE_AA = 36;
constexpr int MAX_PROFILE_AA = 2012;
constexpr int MIN_PROFILE_BP = 108;
constexpr int MAX_PROFILE_BP = 6036;
constexpr int TOTAL_PROFILES = 705;

/**
 * @brief Utility for filtering HMM profiles based on size criteria
 */
struct HMMPicker {
    /**
     * @brief Filter profiles by base pair length
     * @param L Target length in base pairs
     * @return Vector of ProfileSize entries where min_bp < L < max_bp
     */
    static std::vector<ProfileSize> filterByLength(int L) {
        std::vector<ProfileSize> result;
        result.reserve(100);  // Reserve space to avoid reallocations
        bool max_reached = false;
        for (const auto& profile : ALL_PROFILES) {
            if (profile.min_bp < L && L < profile.max_bp) {
                result.push_back(profile);
            }
        }
        
        return result;
    }
};

